package filo.cm.checklist.overlay;

import filo.cm.checklist.CMChecklistConfig;
import filo.cm.checklist.CMChecklistPlugin;
import filo.cm.checklist.data.BrewContext;
import filo.cm.checklist.data.PotionRole;
import filo.cm.checklist.data.save.RoomSetup;
import filo.cm.checklist.data.ItemType;

import java.awt.*;
import java.util.List;
import java.util.ArrayList;
import javax.inject.Inject;

import filo.cm.checklist.util.PotionUtil;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.widgets.WidgetItem;
import net.runelite.client.game.ItemManager;
import net.runelite.client.ui.overlay.WidgetItemOverlay;
import net.runelite.client.util.ColorUtil;
import net.runelite.client.util.ImageUtil;

public class ItemHighlights extends WidgetItemOverlay
{
	private final CMChecklistPlugin plugin;
	private final CMChecklistConfig config;
	private final ItemManager itemManager;

	@Inject
	ItemHighlights(CMChecklistPlugin plugin, CMChecklistConfig config, ItemManager itemManager)
	{
		this.plugin = plugin;
		this.config = config;
		this.itemManager = itemManager;
		showOnInterfaces(
				InterfaceID.RAIDS_STORAGE_PRIVATE,
				InterfaceID.RAIDS_STORAGE_SIDE,
				InterfaceID.INVENTORY
		);
	}

	private BrewContext brewContext;
	@Override
	public Dimension render(Graphics2D graphics)
	{
		if (plugin.getActiveRoomSetup() == null)
			return super.render(graphics);

		restoreRenders = 0;
		brewRenders = 0;

		brewContext = plugin.getBrewContext();
		return super.render(graphics);
	}

	private List<Integer> mismatchedItems = new ArrayList<>();
	private int restoreRenders;
	private int brewRenders;
	@Override
	public void renderItemOverlay(Graphics2D graphics, int itemId, WidgetItem widgetItem)
	{
		if (plugin.getActiveTemplate() == null)
			return;

		RoomSetup templateSetup = plugin.getActiveRoomSetup();
		if (templateSetup == null)
			return;

		int widgetQty = widgetItem.getQuantity();
		int itemIndex = widgetItem.getWidget().getIndex();
		ItemType itemType = templateSetup.getItemType(itemId);
		Rectangle widgetBounds = widgetItem.getCanvasBounds();

		boolean widgetFakeItem = widgetItem.getWidget().getName().isBlank();	// maybe make this better soon
		if (widgetFakeItem)
		{
			if (config.ghostOutline())
				renderItemOverlay(graphics, itemId, widgetQty, config.ghostColour(), widgetBounds, false);

			return;
		}

		int containerGroupId = widgetItem.getWidget().getId() >> 16;
		if (mismatchedItems.contains(itemIndex) && config.highlightMismatched())
		{
			if (containerGroupId != InterfaceID.RAIDS_STORAGE_PRIVATE)
			{
				graphics.setColor(config.highlightMismatchedColour());
				graphics.drawRect(widgetBounds.x, widgetBounds.y, widgetBounds.width, widgetBounds.height);
			}
		}

		if (itemIndexes.contains(itemIndex) && (!config.zigzag() || !config.zigzagInventory()) && config.highlightInventory())
		{
			if (containerGroupId == InterfaceID.RAIDS_STORAGE_PRIVATE)
				renderItemOverlay(graphics, itemId, widgetQty, config.inventoryColour(), widgetBounds, true);
		}

		PotionRole role = PotionUtil.getRole(itemId);
		if (role == PotionRole.BREW && brewContext != null)
		{
			if (brewContext.isSkipRoom())
				return;

			int withdrawQuantity = brewContext.getMissingBrews() - brewRenders;
			int depositQuantity = brewContext.getSurplusBrews() - brewRenders;

			boolean isRendered = renderPotionWarnings(graphics, withdrawQuantity, depositQuantity, itemId, widgetQty, widgetBounds, containerGroupId);
			if (isRendered)
				brewRenders++;

			return;
		}

		if (role == PotionRole.RESTORE && brewContext != null)
		{
			if (brewContext.isSkipRoom())
				return;

			int withdrawQuantity = brewContext.getMissingRestores() - restoreRenders;
			int depositQuantity = brewContext.getSurplusRestores() - restoreRenders;

			boolean isRendered = renderPotionWarnings(graphics, withdrawQuantity, depositQuantity, itemId, widgetQty, widgetBounds, containerGroupId);
			if (isRendered)
				restoreRenders++;

			return;
		}

		switch (itemType)
		{
			case NONE:
			case INVENTORY:
				return;
			case EQUIPMENT:
				if (config.highlightEquipment())
					renderItemOverlay(graphics, itemId, widgetQty, config.equipmentColour(), widgetBounds, true);
				break;
			case WITHDRAW:
				if (containerGroupId != InterfaceID.RAIDS_STORAGE_PRIVATE)	// No inventory
					return;

				if (config.highlightWithdraw())
					renderItemOverlay(graphics, itemId, widgetQty, config.withdrawColour(), widgetBounds, true);
				break;
			case DEPOSIT:
				if (containerGroupId == InterfaceID.RAIDS_STORAGE_PRIVATE)	// Only inventory
					return;

				if (config.highlightDeposit())
					renderItemOverlay(graphics, itemId, widgetQty, config.depositColour(), widgetBounds, true);
				break;
		}
	}


	private boolean renderPotionWarnings(Graphics2D graphics, int withdrawQty, int depositQty, int itemId, int widgetQty, Rectangle widgetBounds, int containerGroupId)
	{
		if (withdrawQty > 0)
		{
			if (containerGroupId != InterfaceID.RAIDS_STORAGE_PRIVATE)
				return false;

			renderItemOverlay(graphics, itemId, widgetQty, config.withdrawColour(), widgetBounds, true);
			return true;
		}

		if (depositQty > 0)
		{
			renderItemOverlay(graphics, itemId, widgetQty, config.depositColour(), widgetBounds, true);
			return true;
		}

		return false;
	}

	private void renderItemOverlay(Graphics2D graphics, int itemId, int itemQty, Color color, Rectangle bounds, boolean fill)
	{
		graphics.drawImage(
				itemManager.getItemOutline(itemId, itemQty, color),
				(int) bounds.getX(),
				(int) bounds.getY(),
				null
		);

		if (!fill)
			return;

		graphics.drawImage(
				getFillImage(color, itemId, itemQty),
				(int) bounds.getX(),
				(int) bounds.getY(),
				null
		);
	}

	private Image getFillImage(Color color, int itemId, int qty)
	{
		final Color fillColor = ColorUtil.colorWithAlpha(color, 72);
        return ImageUtil.fillImage(itemManager.getImage(itemId, qty, false), fillColor);
	}

	private List<Integer> itemIndexes = new ArrayList<>();
	public void updateInventoryItems(List<Integer> itemIndex)
	{
		itemIndexes = itemIndex;
	}

	public void updateMismatchedItems(List<Integer> mismatchIndexes)
	{
		this.mismatchedItems = mismatchIndexes;
	}

	public void clearIndexes()
	{
		this.mismatchedItems.clear();
	}
}

package filo.cm.checklist.panel.comp.preset;

import com.google.gson.Gson;
import com.google.gson.JsonSyntaxException;
import filo.cm.checklist.CMChecklistPlugin;
import filo.cm.checklist.data.save.RaidSetup;
import filo.cm.checklist.util.SaveManager;
import lombok.extern.slf4j.Slf4j;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.PluginPanel;
import net.runelite.client.ui.components.IconTextField;
import net.runelite.client.util.ImageUtil;
import net.runelite.client.util.SwingUtil;
import javax.swing.*;
import javax.swing.event.DocumentEvent;
import javax.swing.event.DocumentListener;
import java.awt.*;
import java.awt.datatransfer.DataFlavor;
import java.awt.datatransfer.UnsupportedFlavorException;
import java.awt.image.BufferedImage;
import java.io.IOException;
import java.util.List;
import java.util.stream.Collectors;

@Slf4j
public class PresetPanel extends JPanel
{
    private final CMChecklistPlugin plugin;
    private final SaveManager saveManager;
    private final Gson gson;

    private final IconTextField searchBar = new IconTextField();
    private final JPanel presetListPanel = new JPanel();

    private static final ImageIcon ADD_ICON;
    private static final ImageIcon ADD_ICON_HOVERED;
    private static final ImageIcon ADD_IMPORT;
    private static final ImageIcon ADD_IMPORT_HOVERED;

    static
    {
        final BufferedImage renameIcon = ImageUtil.loadImageResource(CMChecklistPlugin.class, "add_icon.png");
        final BufferedImage clipboardIcon = ImageUtil.loadImageResource(CMChecklistPlugin.class, "clipboard_add.png");
        ADD_ICON = new ImageIcon(renameIcon);
        ADD_ICON_HOVERED = new ImageIcon(ImageUtil.alphaOffset(renameIcon, -220));
        ADD_IMPORT = new ImageIcon(clipboardIcon);
        ADD_IMPORT_HOVERED = new ImageIcon(ImageUtil.alphaOffset(clipboardIcon, -220));
    }

    public PresetPanel(CMChecklistPlugin plugin, SaveManager saveManager) {
        this.plugin = plugin;
        this.saveManager = saveManager;
        this.gson = plugin.getGson();

        setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
        setAlignmentX(Component.LEFT_ALIGNMENT);

        JLabel headerLabel = new JLabel("CM Storage");
        headerLabel.setAlignmentX(Component.LEFT_ALIGNMENT);

        JPanel headerPanel = new JPanel(new BorderLayout());
        JPanel buttonPanel = new JPanel(new BorderLayout());

        JButton createButton = createButton(ADD_ICON, ADD_ICON_HOVERED, () -> {
            String name = JOptionPane.showInputDialog("Enter a name for the new setup:");
            if (name != null && !name.isEmpty())
            {
                saveManager.createSetup(name);
                refreshPresets();
            }
        });

        JButton importButton = createButton(ADD_IMPORT, ADD_IMPORT_HOVERED, () -> {
            RaidSetup importedSetup = requestClipboardSetup();
            if (importedSetup == null)
                return;
            if (importedSetup.getId() == null)
                return;

            saveManager.importSetup(importedSetup);
            refreshPresets();
        });

        buttonPanel.add(createButton, BorderLayout.WEST);
        buttonPanel.add(importButton, BorderLayout.EAST);
        headerPanel.add(headerLabel, BorderLayout.WEST);
        headerPanel.add(buttonPanel, BorderLayout.EAST);

        add(headerPanel);
        add(Box.createVerticalStrut(5));

        presetListPanel.setLayout(new BoxLayout(presetListPanel, BoxLayout.Y_AXIS));
        presetListPanel.add(Box.createVerticalGlue());

        searchBar.setIcon(IconTextField.Icon.SEARCH);
        searchBar.setPreferredSize(new Dimension(PluginPanel.PANEL_WIDTH - 20, 30));

        searchBar.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        searchBar.getDocument().addDocumentListener(new DocumentListener()
        {
            @Override
            public void insertUpdate(DocumentEvent e)
            {
                refreshPresets();
            }

            @Override
            public void removeUpdate(DocumentEvent e)
            {
                refreshPresets();
            }

            @Override
            public void changedUpdate(DocumentEvent e)
            {
                refreshPresets();
            }
        });

        add(searchBar);

        add(Box.createVerticalStrut(7));
        refreshPresets();
        add(presetListPanel);
    }

    private void refreshPresets()
    {
        SwingUtilities.invokeLater(() -> {
            presetListPanel.removeAll();

            if (saveManager.getRaidSetupList() != null) {
                for (RaidSetup room : searchResults(saveManager.getRaidSetupList(), searchBar.getText())) {
                    presetListPanel.add(new PresetEntry(plugin, saveManager, room));
                    presetListPanel.add(Box.createVerticalStrut(3));
                }
            }

            presetListPanel.revalidate();
        });
    }

    private List<RaidSetup> searchResults(List<RaidSetup> presetList, String query)
    {
        if (query.isBlank())
            return presetList;

        return presetList.stream()
                .filter(e -> e.getName().toLowerCase().contains(query.toLowerCase()))
                .collect(Collectors.toList());
    }

    private JButton createButton(ImageIcon icon, ImageIcon hover, Runnable runnable)
    {
        JButton button = new JButton(icon);
        button.setRolloverIcon(hover);
        button.setPreferredSize(new Dimension(20, 20));
        button.setOpaque(true);
        button.addActionListener(e -> runnable.run());
        SwingUtil.removeButtonDecorations(button);
        return button;
    }

    private RaidSetup requestClipboardSetup()
    {
        String clipboard = requestClipboard();
        if (clipboard == null)
            return null;

        RaidSetup importedSetup = null;
        try
        {
            importedSetup = gson.fromJson(clipboard, RaidSetup.class);
        }
        catch (JsonSyntaxException ex)
        {
            log.warn(ex.getMessage());
        }


        return importedSetup;
    }

    private String requestClipboard()
    {
        String clipboard;
        try
        {
            clipboard = Toolkit.getDefaultToolkit()
                    .getSystemClipboard()
                    .getData(DataFlavor.stringFlavor)
                    .toString();
        }
        catch (IOException | UnsupportedFlavorException ex)
        {
            throw new RuntimeException(ex);
        }

        return clipboard;
    }

    public void build()
    {
        presetListPanel.removeAll();
        refreshPresets();
    }
}

package filo.cm.checklist.panel.comp.preset;

import com.google.gson.Gson;
import filo.cm.checklist.CMChecklistPlugin;
import filo.cm.checklist.data.save.RaidSetup;
import filo.cm.checklist.util.SaveManager;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.components.FlatTextField;
import net.runelite.client.util.ImageUtil;
import net.runelite.client.util.SwingUtil;
import javax.swing.*;
import javax.swing.border.EmptyBorder;
import java.awt.*;
import java.awt.datatransfer.StringSelection;
import java.awt.event.KeyAdapter;
import java.awt.event.KeyEvent;
import java.awt.image.BufferedImage;

public class PresetEntry extends JPanel
{
    private static final ImageIcon RENAME_PRESET;
    private static final ImageIcon OPEN_PRESET;
    private static final ImageIcon DELETE_PRESET;
    private static final ImageIcon RENAME_PRESET_HOVERED;
    private static final ImageIcon OPEN_PRESET_HOVERED;
    private static final ImageIcon DELETE_PRESET_HOVERED;

    static
    {
        final BufferedImage renameIcon = ImageUtil.loadImageResource(CMChecklistPlugin.class, "rename.png");
        final BufferedImage openIcon = ImageUtil.loadImageResource(CMChecklistPlugin.class, "visible_icon.png");
        final BufferedImage deleteIcon = ImageUtil.loadImageResource(CMChecklistPlugin.class, "cancel_icon.png");
        RENAME_PRESET = new ImageIcon(renameIcon);
        OPEN_PRESET = new ImageIcon(openIcon);
        DELETE_PRESET = new ImageIcon(deleteIcon);
        RENAME_PRESET_HOVERED = new ImageIcon(ImageUtil.alphaOffset(renameIcon, -220));
        OPEN_PRESET_HOVERED = new ImageIcon(ImageUtil.alphaOffset(openIcon, -220));
        DELETE_PRESET_HOVERED = new ImageIcon(ImageUtil.alphaOffset(deleteIcon, -220));
    }

    private JPanel leftPanel;
    private FlatTextField presetLabel;
    private JLabel presetLabelR;

    private final JPanel rightPanel;
    private final JButton editNameButton;
    private final JButton openPresetButton;
    private final JButton deletePresetButton;

    private final SaveManager saveManager;
    private String name;

    private CMChecklistPlugin plugin;
    public PresetEntry(CMChecklistPlugin plugin, SaveManager saveManager, RaidSetup setup) {
        this.plugin = plugin;
        this.name = setup.getName();
        this.saveManager = saveManager;
        setLayout(new BorderLayout(5, 5));
        setBorder(new EmptyBorder(5, 5, 5, 5));
        setBackground(ColorScheme.BORDER_COLOR);
        setPreferredSize(new Dimension(Integer.MAX_VALUE, 30));
        setMaximumSize(new Dimension(Integer.MAX_VALUE, 30));

        rightPanel = new JPanel();
        rightPanel.setLayout(new BorderLayout(5, 5));
        rightPanel.setBackground(ColorScheme.BORDER_COLOR);
        rightPanel.setOpaque(true);

        leftPanel = new JPanel();
        leftPanel.setLayout(new BorderLayout(5, 5));
        leftPanel.setOpaque(true);

        JPopupMenu menu = createPresetMenu(setup);
        leftPanel.setComponentPopupMenu(menu);
        setComponentPopupMenu(menu);

        editNameButton = createButton(RENAME_PRESET, RENAME_PRESET_HOVERED, () -> {
            showRenameField(setup);
        });

        openPresetButton = createButton(OPEN_PRESET, OPEN_PRESET_HOVERED, () -> {
            cancel(setup);
            plugin.requestStoragePanel(setup);
        });

        deletePresetButton = createButton(DELETE_PRESET, DELETE_PRESET_HOVERED, () -> {
            plugin.requestDeletePreset(setup);
        });

        rightPanel.add(editNameButton, BorderLayout.WEST);
        rightPanel.add(openPresetButton, BorderLayout.CENTER);
        rightPanel.add(deletePresetButton, BorderLayout.EAST);

        showRenameField(setup); //just to make it iinitailized
        showLabel(setup);

        add(rightPanel, BorderLayout.EAST);
        add(leftPanel, BorderLayout.CENTER);
    }

    private JButton createButton(ImageIcon icon, ImageIcon hovered, Runnable runnable)
    {
        JButton button = new JButton(icon);
        button.setRolloverIcon(hovered);
        button.setPreferredSize(new Dimension(16, 16));
        button.setOpaque(true);
        button.addActionListener(e -> runnable.run());
        SwingUtil.removeButtonDecorations(button);

        return button;
    }

    private void showLabel(RaidSetup setup)
    {
        presetLabelR = new JLabel(setup.getName());
        presetLabelR.setOpaque(true);
        presetLabelR.setBackground(ColorScheme.BORDER_COLOR);
        presetLabelR.setToolTipText(setup.getName());
        presetLabelR.setComponentPopupMenu(createPresetMenu(setup));

        leftPanel.removeAll();
        leftPanel.add(presetLabelR, BorderLayout.CENTER);
        leftPanel.revalidate();
        leftPanel.repaint();
    }

    private void showRenameField(RaidSetup setup)
    {
        presetLabel = new FlatTextField();
        presetLabel.setText(setup.getName());
        presetLabel.setBorder(null);
        presetLabel.setEditable(true);
        presetLabel.setBackground(ColorScheme.BORDER_COLOR);
        presetLabel.addKeyListener(new KeyAdapter() {
            @Override
            public void keyPressed(KeyEvent e) {
                if (e.getKeyCode() == KeyEvent.VK_ENTER) {
                    save(setup);
                }
                if (e.getKeyCode() == KeyEvent.VK_ESCAPE) {
                    cancel(setup);
                }
            }
        });

        leftPanel.removeAll();
        leftPanel.add(presetLabel, BorderLayout.CENTER);
        leftPanel.revalidate();
        leftPanel.repaint();

        presetLabel.requestFocusInWindow();
    }

    private JPopupMenu createPresetMenu(RaidSetup setup)
    {
        JPopupMenu menu = new JPopupMenu();

        JMenuItem export = new JMenuItem("Export Preset");
        export.addActionListener(e -> copySetupToClipboard(setup));

        JMenuItem moveup = new JMenuItem("Move  Up");
        moveup.addActionListener(e -> {
            saveManager.moveSetup(setup, -1);
            plugin.rebuildPresetPanel();
        });

        JMenuItem movedown = new JMenuItem("Move Down");
        movedown.addActionListener(e -> {
            saveManager.moveSetup(setup, 1);
            plugin.rebuildPresetPanel();
        });

        menu.add(export);
        menu.addSeparator();
        menu.add(moveup);
        menu.add(movedown);

        return menu;
    }

    private void copySetupToClipboard(RaidSetup setup)
    {
        Gson gson = plugin.getGson();
        String json = gson.toJson(setup);
        Toolkit.getDefaultToolkit()
                .getSystemClipboard()
                .setContents(new StringSelection(json), null);
    }

    public void save(RaidSetup setup)
    {
        presetLabel.setEditable(false);
        name = presetLabel.getText();
        boolean renamed = saveManager.renameSetup(setup.getId(), name);

        if (!renamed)
            presetLabel.setText(setup.getName());

        showLabel(setup);
    }

    public void cancel(RaidSetup setup)
    {
        presetLabel.setEditable(false);
        presetLabel.setText(setup.getName());
        showLabel(setup);
    }
}

package filo.cm.checklist.panel.comp.storage;

import javax.swing.JPanel;
import javax.swing.border.EmptyBorder;
import filo.cm.checklist.data.InstanceTemplate;
import filo.cm.checklist.data.ItemType;
import filo.cm.checklist.data.save.RoomSetup;
import filo.cm.checklist.util.ItemBoxFactory;
import net.runelite.client.util.SwingUtil;
import java.awt.*;
import java.util.ArrayList;
import java.util.List;

public class EquipmentPanel extends JPanel
{
	// {-1, -1} is null entries, usually like jaw slot or something to skip making box
	private static final int[][] BOX_COORD =
			{
					{1, 0},
					{0, 1}, {1, 1},
					{0, 2},	{1, 2}, {2, 2},
					{-1, -1},
					{1, 3},
					{-1, -1},
					{0, 4}, {1, 4}, {-1, -1}, {2, 4}, {2, 1}
			};

	private final ItemBoxFactory itemBoxFactory;

	public EquipmentPanel(ItemBoxFactory itemBoxFactory, InstanceTemplate template)
	{
		this.itemBoxFactory = itemBoxFactory;

		setLayout(new GridBagLayout());
		setBorder(new EmptyBorder(2, 30, 2, 30));

		build(template, null);
	}

	public void build(InstanceTemplate template, RoomSetup setup)
	{
		List<Integer> equipmentIds = setup != null ? setup.getEquippedItems() : new ArrayList<>();
		SwingUtil.fastRemoveAll(this);

		GridBagConstraints gbc = new GridBagConstraints();
		gbc.insets = new Insets(1,1,1,1);

		for (int i = 0; i < BOX_COORD.length; i++)
		{
			int boxX = BOX_COORD[i][0];
			int boxY = BOX_COORD[i][1];
			if (boxX == -1 || boxY == -1)
				continue;

			gbc.gridx = boxX;
			gbc.gridy = boxY;
			ItemBox itemBox = itemBoxFactory.createItemBox(i, ItemType.EQUIPMENT, template);

			if (i < equipmentIds.size())
				itemBox.setItemById(equipmentIds.get(i));

			add(itemBox, gbc);
		}
	}
}

package filo.cm.checklist.panel.comp.storage;

import filo.cm.checklist.CMChecklistConfig;
import filo.cm.checklist.CMChecklistPlugin;
import filo.cm.checklist.data.InstanceTemplate;
