import net.runelite.client.util.ImageUtil;
import net.runelite.client.util.SwingUtil;
import javax.swing.*;
import java.awt.*;
import java.awt.image.BufferedImage;

public class StoragePanel extends JPanel
{
    private final RaidRoomPanel elevatorPanel;

    private final EquipmentPanel equipmentPanel;
    private final InventoryPanel inventoryPanel;
    private final TaggedItemsPanel depositPanel;
    private final TaggedItemsPanel withdrawPanel;

    private final JLabel equipmentLabel;
    private final JLabel inventoryLabel;
    private final JLabel depositLabel;
    private final JLabel withdrawLabel;

    private static final ImageIcon SETUP_ICON;
    private static final ImageIcon SETUP_ICON_HOVERED;
    private static final ImageIcon BACKPACK_ICON;
    private static final ImageIcon BACKPACK_ICON_HOVERED;
    private static final ImageIcon EQUIP_ICON;
    private static final ImageIcon EQUIP_ICON_HOVERED;
    private static final ImageIcon EXIT_ICON;
    private static final ImageIcon EXIT_ICON_HOVERED;

    static
    {
        final BufferedImage setupIcon = ImageUtil.loadImageResource(CMChecklistPlugin.class, "update_all.png");
        final BufferedImage backpackIcon = ImageUtil.loadImageResource(CMChecklistPlugin.class, "backpack.png");
        final BufferedImage equipIcon = ImageUtil.loadImageResource(CMChecklistPlugin.class, "invent.png");
        final BufferedImage exitIcon = ImageUtil.loadImageResource(CMChecklistPlugin.class, "delete_icon.png");
        SETUP_ICON = new ImageIcon(setupIcon);
        SETUP_ICON_HOVERED  = new ImageIcon(ImageUtil.alphaOffset(setupIcon, -220));
        BACKPACK_ICON = new ImageIcon(backpackIcon);
        BACKPACK_ICON_HOVERED = new ImageIcon(ImageUtil.alphaOffset(backpackIcon, -220));
        EQUIP_ICON = new ImageIcon(equipIcon);
        EQUIP_ICON_HOVERED = new ImageIcon(ImageUtil.alphaOffset(equipIcon, -220));
        EXIT_ICON = new ImageIcon(exitIcon);
        EXIT_ICON_HOVERED = new ImageIcon(ImageUtil.alphaOffset(exitIcon, -220));
    }

    private final CMChecklistPlugin plugin;
    private final SaveManager saveManager;
    private InstanceTemplate template;
    public StoragePanel(
            CMChecklistPlugin plugin,
            CMChecklistConfig config,
            SaveManager saveManager,
            ItemBoxFactory itemBoxFactory,
            InstanceTemplate template
    )
    {
        this.plugin = plugin;
        this.template = template;
        this.saveManager = saveManager;
        setLayout(new BoxLayout(this, BoxLayout.Y_AXIS));
        setAlignmentX(CENTER_ALIGNMENT);

        elevatorPanel = new RaidRoomPanel(plugin, config);
        equipmentPanel = new EquipmentPanel(itemBoxFactory, template);
        inventoryPanel = new InventoryPanel(itemBoxFactory, template);
        depositPanel = new TaggedItemsPanel(saveManager, itemBoxFactory, template, true);
        withdrawPanel = new TaggedItemsPanel(saveManager, itemBoxFactory, template, false);
        equipmentLabel = new JLabel("Equipment");
        inventoryLabel = new JLabel("Inventory");
        depositLabel = new JLabel("Deposit");
        withdrawLabel = new JLabel("Withdraw");

        build();
    }


    public JPanel createHeader()
    {
        final String FAILED_MSG = "Failed to save preset.";
        final String FAILED_TITLE = "Save Failed";

        JLabel setupName = new JLabel("Setup Name");

        RaidSetup setup = saveManager.getActiveSetup();
        if (setup != null)
            setupName.setText(setup.getName());

        RoomSetup roomSetup = saveManager.getRoom(template); // null is fine for ppanels + savemanager

        setupName.setFont(FontManager.getRunescapeBoldFont());

        JPanel headerPanel = new JPanel(new BorderLayout(5, 5));

        JPanel headerControlPanel = new JPanel();
        headerControlPanel.setLayout(new BoxLayout(headerControlPanel, BoxLayout.X_AXIS));

        JButton updateAll = createButton(SETUP_ICON, SETUP_ICON_HOVERED, true, () -> {
            saveManager.saveAll(template, saved -> {
                if (saved) {
                    build();
                    inventoryPanel.build(template, roomSetup);
                    equipmentPanel.build(template, roomSetup);
                }
                else
                    JOptionPane.showMessageDialog(
                            null,
                            FAILED_MSG,
                            FAILED_TITLE,
                            JOptionPane.ERROR_MESSAGE
                    );
            });
        });

        JButton updateInventory = createButton(BACKPACK_ICON, BACKPACK_ICON_HOVERED, true, () -> {
            saveManager.saveInventory(template, saved -> {
                if (saved) {
                    build();
                    inventoryPanel.build(template, roomSetup);
                }
                else
                    JOptionPane.showMessageDialog(
                            null,
                            FAILED_MSG,
                            FAILED_TITLE,
                            JOptionPane.ERROR_MESSAGE
                    );
            });
        });

        JButton updateEquipment = createButton(EQUIP_ICON, EQUIP_ICON_HOVERED, true, () -> {
            saveManager.saveEquipment(template, saved -> {
                if (saved)
                {
                    build();
                    equipmentPanel.build(template, roomSetup);
                }
                else
                    JOptionPane.showMessageDialog(
                            null,
                            FAILED_MSG,
                            FAILED_TITLE,
                            JOptionPane.ERROR_MESSAGE
                    );
            });
        });

        JButton exitPreset = createButton(EXIT_ICON, EXIT_ICON_HOVERED, false, () -> {
            closeSetup();
            elevatorPanel.build();
            plugin.requestClosePreset();
            saveManager.setActiveSetup(null);
        });

        headerControlPanel.add(updateAll);
        headerControlPanel.add(updateInventory);
        headerControlPanel.add(updateEquipment);
        headerControlPanel.add(exitPreset);

        headerPanel.add(setupName, BorderLayout.CENTER);
        headerPanel.add(headerControlPanel, BorderLayout.EAST);
        return headerPanel;
    }

    private JButton createButton(ImageIcon icon, ImageIcon hover, boolean needLogin, Runnable runnable)
    {
        JButton button = new JButton(icon);
        button.setRolloverIcon(hover);
        button.setOpaque(true);
        button.setPreferredSize(new Dimension(20, 20));
        if (needLogin)
            addListener(button, runnable);
        else
            button.addActionListener(e -> runnable.run());
        SwingUtil.removeButtonDecorations(button);
        return button;
    }

    private void addListener(JButton button, Runnable action)
    {
        button.addActionListener(e -> {
            if (saveManager.loggedOut())
            {
                JOptionPane.showMessageDialog(
                        null,
                        "You must be logged in to update a preset.",
                        "Not Logged In",
                        JOptionPane.ERROR_MESSAGE
                );
                return;
            }

            if (template == null)
            {
                JOptionPane.showMessageDialog(
                        null,
                        "You must have a room selected to update it.",
                        "No Room Selected",
                        JOptionPane.ERROR_MESSAGE
                );
                return;
            }

            int choice = JOptionPane.showConfirmDialog(
                    null,
                    "Are you sure you want to update this preset?",
                    "Update Preset",
                    JOptionPane.YES_NO_OPTION
            );

            if (choice == JOptionPane.YES_OPTION)
            {
                action.run();
            }
        });
    }

    public void build()
    {
        removeAll();

        add(createHeader());
        add(Box.createVerticalStrut(15));

        addCenteredComp(elevatorPanel);
        add(Box.createVerticalStrut(5));

        if (template == null)
        {
            PluginErrorPanel errorPanel = new PluginErrorPanel();
            errorPanel.setContent(
                    "No room selected",
                    "Select a room from the above panel, and the setup will be loaded here."
            );
            addCenteredComp(errorPanel);

            return;
        }

        JLabel templateLabel = new JLabel(template.getRoomName());
        templateLabel.setFont(FontManager.getDefaultBoldFont());

        addCenteredComp(templateLabel);
        add(Box.createVerticalStrut(5));

        addCenteredComp(equipmentLabel);
        addCenteredComp(equipmentPanel);
        add(Box.createVerticalStrut(5));

        addCenteredComp(inventoryLabel);
        addCenteredComp(inventoryPanel);
        add(Box.createVerticalStrut(5));

        addCenteredComp(withdrawLabel);
        addCenteredComp(withdrawPanel);
        add(Box.createVerticalStrut(5));

        addCenteredComp(depositLabel);
        addCenteredComp(depositPanel);

        revalidate();
        repaint();
    }

    private void addCenteredComp(JComponent component)
    {
        component.setAlignmentX(CENTER_ALIGNMENT);
        component.setMaximumSize(component.getPreferredSize());
        add(component);
        add(Box.createVerticalStrut(5));
    }

    public void loadFromSetup(InstanceTemplate template, RoomSetup setup)
    {
        this.template = template;

        elevatorPanel.setFloor(template.getPlayerFloor());

        equipmentPanel.build(template, setup);
        inventoryPanel.build(template, setup);
        depositPanel.loadFromSetup(template, setup);
        withdrawPanel.loadFromSetup(template, setup);

        build();
        revalidate();
        repaint();
    }

    private void closeSetup()
    {
        this.template = null;
        revalidate();
        repaint();
    }
}

package filo.cm.checklist.panel.comp.storage;

import java.awt.*;
import java.util.ArrayList;
import java.util.List;
import javax.swing.*;
import javax.swing.border.MatteBorder;
import filo.cm.checklist.data.InstanceTemplate;
import filo.cm.checklist.data.ItemType;
import filo.cm.checklist.data.save.RoomSetup;
import filo.cm.checklist.util.ItemBoxFactory;
import filo.cm.checklist.util.SaveManager;
import net.runelite.client.util.SwingUtil;

public class TaggedItemsPanel extends JPanel
{
	private final boolean isDeposit;
	private final SaveManager saveManager;
	private final ItemBoxFactory itemBoxFactory;
	private InstanceTemplate template;

	public TaggedItemsPanel(
			SaveManager saveManager,
			ItemBoxFactory itemBoxFactory,
			InstanceTemplate template,
			boolean isDeposit
	)
	{
		this.isDeposit = isDeposit;
		this.saveManager = saveManager;
		this.itemBoxFactory = itemBoxFactory;
		this.template = template;

		setBorder(new MatteBorder(1, 1, 1, 1, isDeposit ? Color.RED : Color.GREEN));
		build(template, null);
	}

	public void loadFromSetup(InstanceTemplate template, RoomSetup setup)
	{
		this.template = template;
		build(template, setup);
	}

	private List<Integer> getTaggedItems(RoomSetup setup)
	{
		if (setup == null)
			return new ArrayList<>();

		return isDeposit
				? setup.getTaggedDepositItems()
				: setup.getTaggedWithdrawItems();
	}

	private void build(InstanceTemplate template, RoomSetup setup)
	{
		SwingUtil.fastRemoveAll(this);
		List<Integer> itemIds = setup == null ? new ArrayList<>() : getTaggedItems(setup);
		int itemCount = itemIds.size();
		int rows = itemCount / 4 + 1;

		setLayout(new GridLayout(rows, 4, 2, 2));
		for (int i = 0; i < rows * 4; i++)
		{
			ItemType type = isDeposit ? ItemType.DEPOSIT : ItemType.WITHDRAW;
			ItemBox itemBox = itemBoxFactory.createItemBox(i, type, template, this::refreshCallback);

			if (i < itemCount)
				itemBox.setItemById(itemIds.get(i));

			add(itemBox);
		}

		setMaximumSize(getPreferredSize());
	}

	private void refreshCallback()
	{
		RoomSetup room = saveManager.getRoom(template);
		build(template, room);
	}
}

package filo.cm.checklist.panel.comp.storage;

import java.awt.BorderLayout;
import java.awt.Dimension;
import javax.swing.*;
import javax.swing.border.EmptyBorder;
import filo.cm.checklist.data.InstanceTemplate;
import filo.cm.checklist.data.ItemType;
import filo.cm.checklist.util.SaveManager;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Item;
import net.runelite.api.ItemComposition;
import net.runelite.api.ItemContainer;
import net.runelite.api.gameval.InventoryID;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.chatbox.ChatboxItemSearch;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.util.AsyncBufferedImage;

public class ItemBox extends JPanel
{
	private final JLabel itemLabel;
	private final ChatboxItemSearch chatboxItemSearch;
	private final ClientThread clientThread;
	private final Client client;
	private final SaveManager saveManager;
	private final ItemManager itemManager;
	private final InstanceTemplate template;
	private final Runnable refresh;

	public ItemBox(ClientThread clientThread,
				   Client client,
				   SaveManager saveManager,
				   ItemManager itemManager,
				   int idx,
				   ItemType type,
				   ChatboxItemSearch chatboxItemSearch,
				   InstanceTemplate template,
				   Runnable refresh
	)
	{
		this.clientThread = clientThread;
		this.client = client;
		this.chatboxItemSearch = chatboxItemSearch;
		this.saveManager = saveManager;
		this.itemManager = itemManager;
		this.template = template;
		this.refresh = refresh;

		itemLabel = new JLabel();
		setLayout(new BorderLayout());
		setBorder(new EmptyBorder(2, 2, 2, 2));

		Dimension pref = new Dimension(37, 37);
		setPreferredSize(pref);
		setMaximumSize(pref);
		setMinimumSize(pref);

		setBackground(ColorScheme.DARKER_GRAY_COLOR);
		add(itemLabel, BorderLayout.CENTER);

		if (template != null)
			addPopupMenu(idx, type);
	}

	public void setItemById(int itemId)
	{
		if (itemId <= 0)
		{
			SwingUtilities.invokeLater(() -> {
				itemLabel.setIcon(null);
				itemLabel.setToolTipText("");
				itemLabel.repaint();
				itemLabel.revalidate();
			});
			return;
		}

		AsyncBufferedImage icon = itemManager.getImage(itemId);
		clientThread.invokeLater(() -> {
			ItemComposition itemComposition = itemManager.getItemComposition(itemId);
			String tooltip = itemComposition.getMembersName();

			SwingUtilities.invokeLater(() -> {
				icon.addTo(itemLabel);
				itemLabel.setToolTipText(tooltip);
				itemLabel.revalidate();
				itemLabel.repaint();
				revalidate();
				repaint();
			});
		});
	}

	private void addPopupMenu(int idx, ItemType type)
	{
		JPopupMenu popupMenu = new JPopupMenu();

		JMenuItem replaceFromInventory = new JMenuItem("Update from Inventory");
		replaceFromInventory.addActionListener(e -> {
			updateFromInventory(idx, type);
		});

		JMenuItem addFromSearch = new JMenuItem("Add from search");
		addFromSearch.addActionListener(e -> {
			searchForItem(idx, type);
		});

		JMenuItem removeItem = new JMenuItem("Clear Slot");
		removeItem.addActionListener(e -> {
			removeItem(idx, type);
		});


		if (type == ItemType.EQUIPMENT)
			replaceFromInventory.setText("Update from Equipment");
		if (type != ItemType.DEPOSIT && type != ItemType.WITHDRAW)
			popupMenu.add(replaceFromInventory);
		popupMenu.add(addFromSearch);
		popupMenu.add(removeItem);

		setComponentPopupMenu(popupMenu);
		itemLabel.setComponentPopupMenu(popupMenu);
	}

	private void updateFromInventory(int idx, ItemType type)
	{
		clientThread.invokeLater(() -> {
			boolean isInventory = type == ItemType.INVENTORY;
			ItemContainer itemContainer = client.getItemContainer(isInventory ? InventoryID.INV : InventoryID.WORN);

			if (itemContainer == null)
			{
				SwingUtilities.invokeLater(() -> JOptionPane.showMessageDialog(
                        this,
                        "Could not access inventory."
                ));
				return;
			}

            Item[] playerItems = itemContainer.getItems();
			int itemId = playerItems.length > idx
					? playerItems[idx].getId()
					: -1;

			// I forget why I used the Consumer version here
			saveManager.updateItem(
					idx,
					type,
					itemId,
					template,
					status ->
			{
				SwingUtilities.invokeLater(() -> {
					if (status && refresh != null)
						refresh.run();
					else if (status)
						setItemById(itemId);
				});
			});
		});
	}

	private void searchForItem(int idx, ItemType type)
	{
		clientThread.invokeLater(() -> {
			if (client.getGameState() != GameState.LOGGED_IN)
			{
				SwingUtilities.invokeLater(() ->
						JOptionPane.showMessageDialog(
								this,
								"You must be logged in to search for items."
						)
				);

				return;
			}

			chatboxItemSearch
					.tooltipText("Change Item ():")
					.onItemSelected((itemId) ->
					{
						saveManager.updateItem(
								idx,
								type,
								itemId,
								template
						);
						SwingUtilities.invokeLater(() -> {
							if ((type == ItemType.DEPOSIT
								|| type == ItemType.WITHDRAW)
								&& refresh != null)
							{
								refresh.run();
							}
							else {
								setItemById(itemId);
							}
						});
					})
					.build();
		});
	}

	private void removeItem(int idx, ItemType type)
	{
		clientThread.invokeLater(() ->
		{
			saveManager.updateItem(
					idx,
					type,
					-1,
					template
			);
			SwingUtilities.invokeLater(() -> {
				if ((type == ItemType.DEPOSIT
					|| type == ItemType.WITHDRAW)
					&& refresh != null)
				{
					refresh.run();
				}
				else
				{
					setItemById(0);
				}
			});
		});
	}
}

package filo.cm.checklist.panel.comp.storage;

import filo.cm.checklist.data.InstanceTemplate;
